//! Static Recovery safety analysis and proof obligations.

use crate::canonical::canonicalize_recovery_contract;
use crate::error::{RecoveryError, kind};
use crate::model::{
    EffectRecoveryClause, IdempotencySemantics, ReconciliationRequirement, RecoveryContract,
    ReplaySemantics, UnknownEffectHandling,
};
use crate::universe::RecoveryOperationUniverse;
use af_effect::{EffectRow, EffectSignature};
use std::collections::BTreeMap;

/// Read-only fact supplied by tests or a future runtime evidence adapter. It
/// is not an EffectReceipt and is never generated by this crate.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum RecoveryEvidenceState {
    Unknown,
    StillUnknown,
    NotApplied,
    Applied,
    PartiallyApplied,
}

/// Stable static obligation names.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum RecoveryObligation {
    DurableRecordedResult,
    ReconciliationEvidence,
    IdempotencyEvidence,
    KeyStabilityEvidence,
    PartialStateResolution,
}

impl RecoveryObligation {
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::DurableRecordedResult => "durable_recorded_result",
            Self::ReconciliationEvidence => "reconciliation_evidence_missing",
            Self::IdempotencyEvidence => "idempotency_evidence_missing",
            Self::KeyStabilityEvidence => "key_stability_evidence_missing",
            Self::PartialStateResolution => "partial_state_resolution_required",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RecoveryUnprovenReason {
    UnknownEffectCoverage,
    MissingClause,
    HistoricalReplayNeedsEvidence,
}

impl RecoveryUnprovenReason {
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::UnknownEffectCoverage => "unknown_effect_coverage",
            Self::MissingClause => "missing_effect_recovery_clause",
            Self::HistoricalReplayNeedsEvidence => "historical_replay_needs_evidence",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RecoveryViolation {
    UnsafeBlindRetry,
    PartiallyAppliedUnresolved,
    EffectQualifierConflict,
}

impl RecoveryViolation {
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::UnsafeBlindRetry => "unsafe_blind_retry",
            Self::PartiallyAppliedUnresolved => "partially_applied_unresolved",
            Self::EffectQualifierConflict => "effect_qualifier_conflict",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RecoveryProof {
    ProvenStaticConstraint,
    RequiresEvidence(Vec<RecoveryObligation>),
    Unproven(RecoveryUnprovenReason),
    Violation(RecoveryViolation),
}

impl RecoveryProof {
    #[must_use]
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::ProvenStaticConstraint => "proven_static_constraint",
            Self::RequiresEvidence(_) => "requires_evidence",
            Self::Unproven(_) => "unproven",
            Self::Violation(_) => "violation",
        }
    }
}

/// Static Recovery safety analysis. Evidence is explicit read-only input;
/// this function never creates a runtime result.
pub fn analyze_recovery_safety(
    contract: &RecoveryContract,
    effect_description: &EffectSignature,
    universe: &RecoveryOperationUniverse,
    evidence: &BTreeMap<af_effect::AtomKey, RecoveryEvidenceState>,
) -> Result<RecoveryProof, RecoveryError> {
    let canonical = canonicalize_recovery_contract(contract, universe)?;
    if canonical.replay_semantics == ReplaySemantics::Recorded {
        return Ok(RecoveryProof::RequiresEvidence(vec![
            RecoveryObligation::DurableRecordedResult,
        ]));
    }
    let effect = effect_description
        .validate(&universe.effects)
        .map_err(|error| RecoveryError::new(kind::RECOVERY_CONTRACT_UNPROVEN, error.to_string()))?;
    let EffectRow::Closed(entries) = effect.row else {
        return Ok(RecoveryProof::Unproven(
            RecoveryUnprovenReason::UnknownEffectCoverage,
        ));
    };
    let clauses: BTreeMap<_, _> = canonical
        .effect_recovery_clauses
        .iter()
        .map(|clause| (af_effect::AtomKey::of(&clause.effect), clause))
        .collect();
    if clauses.keys().any(|key| {
        !entries
            .iter()
            .any(|entry| af_effect::AtomKey::of(&entry.atom) == *key)
    }) {
        return Err(RecoveryError::new(
            kind::RECOVERY_EFFECT_NOT_DECLARED,
            "a recovery clause targets an EffectAtom absent from the Effect Signature",
        ));
    }
    let mut obligations = Vec::new();
    for entry in &entries {
        let key = af_effect::AtomKey::of(&entry.atom);
        let Some(clause) = clauses.get(&key) else {
            return Ok(RecoveryProof::Unproven(
                RecoveryUnprovenReason::MissingClause,
            ));
        };
        let state = evidence
            .get(&key)
            .copied()
            .unwrap_or(RecoveryEvidenceState::Unknown);
        evaluate_clause(canonical.replay_semantics, clause, state, &mut obligations)?;
    }
    if let Some(unmatched) = clauses.keys().find(|key| {
        !entries
            .iter()
            .any(|entry| af_effect::AtomKey::of(&entry.atom) == **key)
    }) {
        let _ = unmatched;
        return Err(RecoveryError::new(
            kind::RECOVERY_EFFECT_NOT_DECLARED,
            "a recovery clause targets an EffectAtom absent from the Effect Signature",
        ));
    }
    obligations.sort();
    obligations.dedup();
    if obligations.is_empty() {
        Ok(RecoveryProof::ProvenStaticConstraint)
    } else {
        Ok(RecoveryProof::RequiresEvidence(obligations))
    }
}

fn evaluate_clause(
    replay: ReplaySemantics,
    clause: &EffectRecoveryClause,
    state: RecoveryEvidenceState,
    obligations: &mut Vec<RecoveryObligation>,
) -> Result<(), RecoveryError> {
    if replay == ReplaySemantics::Forbidden {
        return Ok(());
    }
    if replay == ReplaySemantics::Recompute
        && clause.idempotency == IdempotencySemantics::Natural
        && effect_has_none_qualifier(clause)
    {
        return Err(RecoveryError::new(
            kind::INVALID_IDEMPOTENCY_CONTRACT,
            "natural recovery conflicts with an Effect qualifier declaring none",
        ));
    }
    if replay == ReplaySemantics::Reconcile
        && clause.reconciliation == ReconciliationRequirement::None
    {
        obligations.push(RecoveryObligation::ReconciliationEvidence);
    }
    if let Some(key) = &clause.key_requirement {
        if !key.stable_across_attempts
            || !key.distinct_across_invocations
            || !key.bound_to_operation
        {
            obligations.push(RecoveryObligation::KeyStabilityEvidence);
        }
        if !key.provider_honors {
            obligations.push(RecoveryObligation::IdempotencyEvidence);
        }
    }
    match state {
        RecoveryEvidenceState::PartiallyApplied => {
            obligations.push(RecoveryObligation::PartialStateResolution);
        }
        RecoveryEvidenceState::Unknown | RecoveryEvidenceState::StillUnknown => {
            if clause.unknown_effect_handling == UnknownEffectHandling::Block
                && clause.idempotency == IdempotencySemantics::None
            {
                return Err(RecoveryError::new(
                    kind::UNSAFE_BLIND_RETRY,
                    "NONE idempotency with UNKNOWN effect cannot be blindly retried",
                ));
            }
            if clause.unknown_effect_handling == UnknownEffectHandling::ReconciliationRequired
                || clause.idempotency == IdempotencySemantics::Reconciled
                || clause.reconciliation == ReconciliationRequirement::Required
            {
                obligations.push(RecoveryObligation::ReconciliationEvidence);
            } else {
                obligations.push(RecoveryObligation::IdempotencyEvidence);
            }
        }
        RecoveryEvidenceState::Applied | RecoveryEvidenceState::NotApplied => {}
    }
    Ok(())
}

fn effect_has_none_qualifier(clause: &EffectRecoveryClause) -> bool {
    clause.effect.qualifiers.iter().any(|qualifier| {
        matches!(
            qualifier,
            af_effect::EffectQualifier::Idempotency(af_effect::EffectIdempotencyQualifier::None)
        )
    })
}
